from __future__ import annotations
import numpy as np

def outcome_record(root, pair, result, oracle):
    regret = max(oracle.policy_values.values()) - oracle.policy_values[result.selected_policy]
    return {'root': root.root_context_id, 'profile': root.profile.profile_id, 'pair': [p[0] for p in pair], 'budget': result.budget, 'allocator': result.allocator_id, 'selected_policy': result.selected_policy, 'oracle_best_policy': oracle.best_policy, 'regret': regret, 'best_policy_correct': regret <= 1e-12, 'value_mae': float(np.mean([abs(result.estimated_policy_values[p] - v) for p, v in oracle.policy_values.items()])), 'value_rmse': float(np.sqrt(np.mean([(result.estimated_policy_values[p] - v) ** 2 for p, v in oracle.policy_values.items()]))), 'rank_agreement': float(np.sign(result.estimated_policy_values[pair[0][0]] - result.estimated_policy_values[pair[1][0]]) == np.sign(oracle.policy_values[pair[0][0]] - oracle.policy_values[pair[1][0]])), 'expanded_first_reaction_count': len({n.branch_path[0] for n in result.nodes}), 'expanded_depth_counts': {str(d): sum((n.depth == d for n in result.nodes)) for d in (1, 2)}, 'branch_policy_recipe_disagreement': float(np.mean([n.policy_evidence[0].downstream_action.selected_item.item_id != n.policy_evidence[1].downstream_action.selected_item.item_id for n in result.nodes])), 'estimated_policy_values': result.estimated_policy_values, 'oracle_policy_values': oracle.policy_values, 'oracle_margin': abs(list(oracle.policy_values.values())[0] - list(oracle.policy_values.values())[1]), 'expansions': result.actual_expansions, 'expansion_order': list(result.expansion_order)}
